"""The documentation screenshots are generated by a script; it has to keep working."""

from __future__ import annotations

import importlib.util
from pathlib import Path

import pytest

from rpggen.core import godot
from rpggen.gui.pages.project_page import ProjectPage

REPO = Path(__file__).resolve().parents[2]


@pytest.mark.slow
def test_every_page_screenshot_is_rendered(
    godot_exe: Path, tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    spec = importlib.util.spec_from_file_location(
        "make_doc_screenshots", REPO / "tools" / "make_doc_screenshots.py"
    )
    assert spec and spec.loader
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    # the script patches these for its own run; put them back afterwards
    monkeypatch.setattr(ProjectPage, "documents_dir", ProjectPage.documents_dir)
    monkeypatch.setattr(godot, "auto_find_godot", godot.auto_find_godot)
    monkeypatch.setenv("RPGGEN_CACHE_DIR", str(tmp_path / "cache"))
    written = module.render(tmp_path / "images", godot_exe)  # includes generate and results
    names = {p.name for p in written}
    assert names == {
        "wizard_project.png", "wizard_archetype.png", "wizard_audit.png", "wizard_mapping.png",
        "wizard_options.png", "wizard_generate.png", "wizard_results.png", "crash_dialog.png",
        "welcome.png", "wizard_audit_light.png", "map_preview.png", "about_dialog.png",
        "pack_cards.png", "regeneration_preview.png", "conflict_resolver.png", "storage_dialog.png",
    }  # fmt: skip
    assert all(p.stat().st_size > 500 for p in written)
